def pass_at_k(n, c, k):
    """计算代码生成评测里的 pass@k 无偏估计。"""
    if n <= 0 or c < 0 or c > n or k <= 0:
        raise ValueError("require n > 0, 0 <= c <= n and k >= 1")
    if c == 0:
        return 0.0
    if n - c < k:
        return 1.0
    product = 1.0
    for i in range(n - c + 1, n + 1):
        product *= 1.0 - k / i
    return 1.0 - product


