class SSEParser:
    """增量解析 SSE，并拼接模型文本与工具调用片段。"""
    def __init__(self):
        self.buffer = ""
        self.content = ""
        self.tool_calls = {}
        self.done = False
        self.finish_reason = None
        self.errors = []

    def _snapshot(self):
        calls = []
        for index in sorted(self.tool_calls):
            call = self.tool_calls[index]
            calls.append({"index": index, "function": {"name": call["name"], "arguments": call["arguments"]}})
        return {"content": self.content, "tool_calls": calls, "done": self.done, "finish_reason": self.finish_reason, "errors": list(self.errors)}

    def _handle_event(self, event):
        import json
        data_lines = []
        for raw_line in event.splitlines():
            line = raw_line.rstrip("\r")
            if line.startswith(":"):
                continue
            if line.startswith("data:"):
                value = line[5:]
                if value.startswith(" "):
                    value = value[1:]
                data_lines.append(value)
        if not data_lines:
            return
        data = "\n".join(data_lines).strip()
        if data == "[DONE]":
            self.done = True
            return
        try:
            payload = json.loads(data)
